import sys

def solve():
    t = int(input())
    for _ in range(t):
        n, x = map(int, input().split())
        a = list(map(int, input().split()))
        a.append(x)
        a.sort()
        ans = 0
        for i in range(n+1):
            if i == 0:
                ans = max(ans, a[i])
            else:
                ans = max(ans, a[i]-a[i-1])
        print(ans*2)

