def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        x = input()
        s = input()
        if s in x:
            print(0)
            continue
        ans = math.inf
        for i in range(n):
            k = 1
            while x[:i] * k + x in x:
                k += 1
            if x[:i] * k + x == x[:i] * (k - 1) + s:
                ans = min(ans, k - 1)
        print(ans if ans!= math.inf else -1)

