def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        x = input()
        s = input()
        if s in x:
            print(0)
            continue
        if m == 1:
            print(1)
            continue
        if n >= m:
            print(-1)
            continue
        if m == 2 and s[0] == s[1] and s[0] in x:
            print(1)
            continue
        if m == 2 and s[0] == s[1] and s[0] not in x:
            print(-1)
            continue
        if m == 2 and s[0]!= s[1]:
            for i in range(n):
                if x[i] == s[0]:
                    if x[(i + 1) % n] == s[1]:
                        print(1)
                        break
                    else:
                        print(2)
                        break
            else:
                print(-1)
                break
        l = 1
        while l <= m:
            if s in x * l:
                print(math.ceil(l / n))
                break
            l += 1
        else:
            print(-1)

