def solve():
    n = int(input())
    a = list(map(int, input().split()))
    ans = float('inf')
    for x in a:
        ans = min(ans, abs(x))
    if ans == 0:
        return 0
    for x in a:
        if x!= 0:
            ans = min(ans, math.gcd(abs(x), ans))
    return ans

