def solve():
    x, y, n = map(int, input().split())
    if n == 3 and x + 1 == y:
        return -1
    elif n == 3:
        return x, x + (y - x) // 2, y
    else:
        a = [x]
        diff = y - x
        step = diff // (n - 1)
        for i in range(1, n):
            a.append(a[-1] + max(1, step - i + 1))
        if a[-1] == y:
            return a
        else:
            return -1

def solve():
    t = int(input())
    for _ in range(t):
        x, y, n = map(int, input().split())
        if n == 3:
            if y - x > 1:
                print(x, x + 1, y)
            else:
                print(-1)
        else:
            a = [x]
            b = y - x
            tmp = b // (n - 2)
            for i in range(1, n - 1):
                a.append(a[-1] + max(1, tmp - i + 1))
            a.append(y)
            if all(a[i] < a[i + 1] for i in range(n - 1)) and all(a[i + 1] - a[i] > a[i + 2] - a[i + 1] for i in range(n - 2)):
                print(*a)
            else:
                print(-1)

