from collections import deque

def solve():
    input = sys.stdin.readline
    t = int(input())
    for _ in range(t):
        n = int(input())
        p = list(map(int, input().split()))
        p = deque(p)
        ans = 0
        while True:
            if p[0] == p[-1]:
                p.pop()
                p.popleft()
            elif p[0] == 1:
                p.popleft()
            elif p[-1] == n:
                p.pop()
            else:
                p.appendleft(p.pop())
                ans += 1
            if len(p) == 0:
                break
        print(ans)

