from itertools import permutations

def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        opinions = []
        for __ in range(n):
            opinions.append(input().strip())
        ans = 1
        for p in permutations(range(1, n)):
            remain = set(p)
            for opinion in zip(*opinions):
                agree = sum(1 for i in range(n) if opinion[i] == "+" and i + 1 in remain)
                disagree = k - agree
                if agree > disagree:
                    remain -= set(i for i in range(n) if opinion[i] == "-" and i + 1 in remain)
                elif agree < disagree:
                    remain -= set(i for i in range(n) if opinion[i] == "+" and i + 1 in remain)
                else:
                    remain = set()
                    break
            ans = max(ans, len(remain))
        print(ans)

