from itertools import permutations

def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        opinions = []
        for __ in range(n):
            opinions.append(input().strip())
        max_members = 1
        for p in permutations(range(1, n + 1)):
            members = set(p)
            members.remove(1)
            agree = defaultdict(int)
            disagree = defaultdict(int)
            for i in range(k):
                for j in members:
                    if opinions[j - 1][i] == '+':
                        agree[i] += 1
                    else:
                        disagree[i] += 1
                if agree[i]  disagree[i]:
                    for j in members:
                        if opinions[j - 1][i] == '-':
                            members.remove(j)
                elif agree[i]  disagree[i]:
                    for j in members:
                        if opinions[j - 1][i] == '+':
                            members.remove(j)
                else:
                    members.clear()
                    break
            max_members = max(max_members, len(members))
        print(max_members)

