from collections import defaultdict
from itertools import accumulate

def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        opinions = [input().strip() for _ in range(n)]
        stance = [[0 if opinion[j] == '+' else 1 for opinion in opinions] for j in range(k)]
        agree = [sum(1 - s for s in zip(*stance[j])) for j in range(k)]
        disagree = [sum(stance[j]) for j in range(k)]
        expel = [set() for _ in range(k)]
        for j in range(k):
            if agree[j] > disagree[j]:
                for i in range(n):
                    if stance[i][j]: expel[j].add(i)
            elif agree[j] < disagree[j]:
                for i in range(n):
                    if not stance[i][j]: expel[j].add(i)
            else:
                for i in range(n): expel[j].add(i)
        for i in range(n):
            if i not in accumulate(expel): break
            for j in range(k):
                if stance[i][j] and agree[j] <= disagree[j]: break
                elif not stance[i][j] and agree[j] >= disagree[j]: break
            else: return n - len(set.union(*expel))

