from collections import Counter

def solve():
    s = input()
    counter = Counter(s)
    if len(counter) == 1:
        return -1
    elif len(counter) == 2:
        if counter.most_common(1)[1] == 1:
            return 2 * (len(s) - 1)
        else:
            return len(s)
    else:
        return len(s)

