from collections import deque

def solve():
    input_lines = input()
    test_case_num = int(input_lines[0].strip())
    line_index = 1
    for _ in range(test_case_num):
        n, m = map(int, input_lines[line_index].strip().split())
        line_index += 1
        p_list = list(map(int, input_lines[line_index].strip().split()))
        line_index += 1
        recent_actions = deque(maxlen=n)
        ans = [-1] * n
        for i, p in enumerate(p_list):
            if p in recent_actions:
                recent_actions.remove(p)
            recent_actions.appendleft(p)
            if len(recent_actions) > n:
                recent_actions.pop()
            if i + 1 >= n:
                for j in range(n):
                    if recent_actions[j] not in p_list[i - n + 1:i + 1]:
                        ans[j] = i + 1
        print(*ans)

