        d = deque(range(1, n + 1), maxlen=n)
        ans = [-1] * n
        for i, x in enumerate(p,1):
            if x in d:
                d.remove(x)
                d.appendleft(x)
            else:
                d.appendleft(x)
            if len(d) == n and d[-1] <= n:
                ans[d[-1] - 1] = i + 1
        print(*ans)

