        n = int(input().strip())
        a = input().strip().split()
        s = ""
        for i in range(n):
            if len(a[i]) == 1:
                s += a[i]
                break
        for i in range(n-1, -1, -1):
            if len(a[i]) == 1:
                s = a[i] + s
                break
        l = len(s)
        for i in range(n-1):
            if len(a[i]) == l-1:
                if a[i][:-1] == s[:-1]:
                    s = a[i] + s
                    break
        print("YES" if s == s[::-1] else "NO")

