from collections import deque

def solve():
    input = sys.stdin.readline
    t = int(input)
    for _ in range(t):
        n = int(input())
        a = list(map(int,input().split()))
        q = deque(a)
        while len(q) > 1:
            if q[0] > q[-1]:
                q[0] += q[1]
            else:
                q[1], q[-1] = q[-1], q[1]
            if q[0] <= q[-1]:
                break
        print("Yes" if len(q) == 1 else "No")

