from collections import deque

def solve():
    input = sys.stdin.readline
    t = int(input().strip())
    for _ in range(t):
        n, k = map(int, input().split())
        a = deque(map(int, input().split()))
        while len(a) > 1:
            if a[0] == 0:
                a.popleft()
            elif a[-1] == 0:
                a.pop()
            elif len(a) >= k and all(a[i] == 1 for i in range(k)):
                a = deque([1])
            elif len(a) >= k and any(a[i] == 1 for i in range(k)):
                a = deque([1] + [0] * (len(a) - k)
            else:
                break
        print("YES" if len(a) == 1 and a[0] == 1 else "NO")

