def solve():
    import sys
    input = sys.stdin.readline
    t = int(input.strip())
    for _ in range(t):
        a, b = input().strip().split()
        a = a.replace('M', '1').replace('S', '0').replace('L', '2')
        b = b.replace('M', '1').replace('S', '0').replace('L', '2')
        if a.count('X') > b.count('X'):
            if 'L' in b:
                print('>')
            elif 'M' in b:
                print('>')
            else:
                print('<')
        elif a.count('X') < b.count('X'):
            if 'L' in a:
                print('<')
            elif 'M' in a:
                print('<')
            else:
                print('>')
        else:
            if a[-1] == 'L' and b[-1]!= 'L':
                print('>')
            elif a[-1]!= 'L' and b[-1] == 'L':
                print('<')
            else:
