import re

def solve():
    sizes = {"S": 0, "M": 1, "L": 2}
    patterns = {
        r"^[X]*S$": lambda x: (len(x) - 1, 0),
        r"^[X]*M$": lambda x: (len(x) - 1, 1),
        r"^[X]*L$": lambda x: (len(x) - 1, 2)
    }

    def size(s):
        for pattern, func in patterns.items():
            match = re.match(pattern, s)
            if match:
                return func(match.group())

    t = int(input())
    for _ in range(t):
        a, b = input().split()
        size_a = size(a)
        size_b = size(b)

        if size_a < size_b:
            print("<")
        elif size_a > size_b:
            print(">")
        else:
            print("=")

