from collections import deque
from functools import lru_cache

def solve():
    input = sys.stdin.readline
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        a.append(0)
        b.append(0)
        fire = deque()
        frost = deque()
        for i in range(n + 1):
            if a[i] == 0:
                fire.append(b[i])
            else:
                frost.append(b[i])
        fire = sorted(fire, reverse = True)
        frost = sorted(frost, reverse = True)
        ans = 0
        while fire and frost:
            if fire[0] >= frost[0]:
                ans += fire.popleft() * 2
            else:
                ans += frost.popleft() * 2
        while fire:
            ans += fire.popleft()
        while frost:
            ans += frost.popleft()
        print(ans)

