from collections import Counter

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        a.sort()
        c = Counter(a)
        ans = float('inf')
        for x in c:
            if c[x] >= 3:
                ans = min(ans, 0)
            elif c[x] == 2:
                if c[x + 1] >= 1:
                    ans = min(ans, 1)
                elif c[x + 2] >= 1:
                    ans = min(ans, 2)
                else:
                    for y in c:
                        if y > x + 2:
                            ans = min(ans, y - x)
                            break
            else:
                for y in c:
                    if y > x:
                        ans = min(ans, y - x)
                        break
        print(ans)

