def solve():
    n = int(input())
    min_weight = n
    min_perm = None
    for p in permutations(range(1, n + 1)):
        weight = 0
        for i in range(n):
            if (p[i] % (i + 1) == 0):
                weight += 1
        if weight < min_weight:
            min_weight = weight
            min_perm = p
    print(*min_perm)

