            print("YES" if a[-1] == b[-1] else "NO")
            continue
        if a[-m:] == b:
            print("YES")
            continue
        if a[-1] == b[-1]:
            print("YES")
            continue
        if a[-1]!= b[-1]:
            print("NO")
            continue
        a = a[:-1]
        while len(a) >= m:
            if a[-1] == b[-1]:
                a = a[:-1]
            elif a[-1] < b[-1]:
                a = a[:-1]
            else:
                a = a[:-2]
                a = a[:-1] + str(min(int(a[-2], int(a[-1])) + a[-1:]
        print("YES" if a == b[:-1] else "NO")

